function extract($, ctx) {
  const items = [];
  const seen = new Set();

  // Find each section heading that likely precedes a price list
  $('section.elementor-section h2.elementor-heading-title.elementor-size-default').each(function () {
    const $heading = $(this);
    const section = cleanText($heading.text()) || null;

    // Scope to the current section element
    const $section = $heading.closest('section.elementor-section');
    if (!$section.length) return;

    // Get all menu items inside this section
    $section.find('li.elementor-price-list-item').each(function () {
      const $item = $(this);

      // Title
      const $titleEl = $item.find('span.elementor-price-list-title');
      if (!$titleEl.length) return;
      let name = cleanText($titleEl.text());
      if (!name) return;

      // Description (optional)
      const $descEl = $item.find('p.elementor-price-list-description');
      const description = $descEl.length ? cleanText($descEl.text()) : null;

      // Price (first price shown)
      const $priceEl = $item.find('span.elementor-price-list-price');
      let price = null;
      if ($priceEl.length) {
        const priceText = cleanText($priceEl.text());
        if (priceText) price = parsePrice(priceText);
      }

      // Build dedup key
      const key = `${section || ''}|${name}|${description || ''}|${price === null ? '' : price}`;
      if (seen.has(key)) return;
      seen.add(key);

      items.push({ section, name, description, price });
    });
  });

  return items;
}
```

